def solve(g):
    H,W=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    hL=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and next(iter({g[r][c] for r in range(H)}))!=bg]
    vL=[r for r in range(H) if len({g[r][c] for c in range(W)})==1 and next(iter({g[r][c] for c in range(W)}))!=bg]
    o=[r[:] for r in g]
    cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg and c not in hL and r not in vL]
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    sep='h' if hL else ('v' if vL else None)
    if sep=='h':
        nr=max(rs)+1
        if 0<=nr<H:
            for c in range(W): o[nr][c]=8
    elif sep=='v':
        nc=max(cs)+1
        if 0<=nc<W:
            for r in range(H): o[r][nc]=8
    return o
